import json
rows={}
for l in open('nlchain.jsonl'):
    l=l.strip()
    if l:
        r=json.loads(l)
        if r.get('mode')=='chain': rows[r['Z']]=r
def nlv(t): return int(t[0]),'spdfg'.index(t[1])
hit=0; gate=0; gtot=0
for Z in range(21,31):
    r=rows[Z]; D=dict(r['order'])
    dl={k: D[k]+1/(2*nlv(k)[0]**2) for k in D}
    am=max(dl,key=lambda k: abs(dl[k]))
    hit += (am==r['ent'])
    lmax=2
    for k in D:
        if nlv(k)[1]>=lmax+2:
