    print(f'  Z={Z} ent={r[\"ent\"]} argmax|D|={am} |D|={abs(dl[am]):.5f}  gated={[k for k in D if nlv(k)[1]>=lmax+2]}')
print()
print('PC3D-10 entrant==argmax|Delta| :',hit,'/10','HELD' if hit==10 else 'FAILED')
print('PC3D-11 centrifugal gate       :',gate,'/',gtot,'HELD' if gate==gtot else 'FAILED')
" 2>&1 | tail -16

